/// `GenPassElement.GetTitle()` (UIWorldGenDebug.cs:627)
pub unsafe fn get_title(this: *mut terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::GenPassElement) -> Str {
    if terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::skipped(this)
    {
        return rt::concat(&[s!("Skipped: "), (*(*this).pass.ptr()).name]);
    }
    if (!terraria::world_building::gen_pass::enabled((*this).pass.ptr()))
    {
        return rt::concat(&[s!("Disabled: "), (*(*this).pass.ptr()).name]);
    }
    return rt::concat(&[(if (!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::has_completed(this)) { s!("Run") } else { s!("Rerun") }), s!(" to "), (*(*this).pass.ptr()).name]);
    rt::unreachable()
}

/// `GenPassElement.GetDescription()` (UIWorldGenDebug.cs:640)
pub unsafe fn get_description(this: *mut terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::GenPassElement) -> Str {
    let mut text: Str = s!("");
    if terraria::world_building::gen_pass::enabled((*this).pass.ptr())
    {
        text = rt::concat(&[text, s!("Hold shift to ignore snapshots\n")]);
        if ((!terraria::game_content::ui::states::ui_world_gen_debug::can_submit_actions()) && (terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::has_completed(this) || terraria::utils::pressing_shift((*terraria::main::s()).key_state)))
        {
            text = rt::concat(&[text, s!("[c/FFA500:Must be paused to rerun or load snapshots]\n")]);
        }
    }
    if ((!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::has_completed(this)) && (!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::skipped(this)))
    {
        text = rt::concat(&[text, (if terraria::world_building::gen_pass::enabled((*this).pass.ptr()) { s!("Right click to disable\n") } else { s!("Left click to enable\n") })]);
        text = rt::concat(&[text, s!("Shift to edit ranges\n")]);
    }
    return rt::concat(&[text, s!("Alt click to toggle highlight\n")]);
    rt::unreachable()
}

/// `GenPassElement.GetSnapshotButtonTitle()` (UIWorldGenDebug.cs:659)
pub unsafe fn get_snapshot_button_title(this: *mut terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::GenPassElement) -> Str {
    if ((!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::snapshot(this).is_null()) && terraria::world_building::world_gen_snapshot::outdated(terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::snapshot(this).ptr()))
    {
        return s!("Snapshot is outdated and will only be used for comparison when the pass is run again");
    }
    if (!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::snapshot(this).is_null())
    {
        return s!("Reset to snapshot");
    }
    if (terraria::world_building::world_generator::controller::last_completed_pass(terraria::game_content::ui::states::ui_world_gen_debug::controller().ptr()).addr() == (*this).pass.addr())
    {
        return s!("Take snapshot");
    }
    return Str::NULL;
    rt::unreachable()
}

/// `GenPassElement.GetSnapshotButtonDescription()` (UIWorldGenDebug.cs:676)
pub unsafe fn get_snapshot_button_description(this: *mut terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::GenPassElement) -> Str {
    if (!terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::snapshot(this).is_null())
    {
        let mut text: Str = s!("Left click to load snapshot\n");
        text = rt::concat(&[text, s!("Right click to delete snapshot\n")]);
        if (!terraria::game_content::ui::states::ui_world_gen_debug::can_submit_actions())
        {
            text = rt::concat(&[text, s!("[c/FFA500:Must be paused to load a snapshot]")]);
        }
        return text;
    }
    if (terraria::world_building::world_generator::controller::last_completed_pass(terraria::game_content::ui::states::ui_world_gen_debug::controller().ptr()).addr() == (*this).pass.addr())
    {
        return s!("Left click to take snapshot\n");
    }
    return Str::NULL;
    rt::unreachable()
}

