/// `GenPassElement.ToggleHighlight()` (UIWorldGenDebug.cs:720)
pub unsafe fn toggle_highlight(this: *mut terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::GenPassElement) {
    if terraria::game_content::ui::states::ui_world_gen_debug::gen_pass_element::is_highlighted(this)
    {
        let _ = (*(*(*terraria::game_content::ui::states::ui_world_gen_debug::config::s()).instance.ptr()).highlighted_pass_names.ptr()).remove(rt::wbv((*(*this).pass.ptr()).name));
    }
    else
    {
        let _ = (*(*(*terraria::game_content::ui::states::ui_world_gen_debug::config::s()).instance.ptr()).highlighted_pass_names.ptr()).add(rt::wbv((*(*this).pass.ptr()).name));
    }
    terraria::game_content::ui::states::ui_world_gen_debug::config::save();
}

